// The first sixteen Fibonacci numbers, on one line
fn fib(n) {
    if n < 2 {
        return n
    }
    return fib(n - 1) + fib(n - 2)
}
let line = ""
let i = 0
while i <= 15 {
    if i > 0 {
        line = line + " "
    }
    line = line + str(fib(i))
    i = i + 1
}
print(line)

fn fact(n) {
    if n <= 1 {
        return 1
    }
    return n * fact(n - 1)
}
fn fact_loop(n) {
    let result = 1
    while n > 1 {
        result = result * n
        n = n - 1
    }
    return result
}
print(fact(10))
print(fact(20))
print(fact(12) == fact_loop(12))
print(fact(21))

